44	    <rect x="11" y="9.5" width="14" height="5" rx="2" fill="var(--accent)"/>
45	    <rect x="28" y="9.5" width="14" height="5" rx="2" fill="currentColor"/>
46	    <path d="M48 31H32M39 24L32 31L39 38" stroke="var(--accent)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
47	  </svg>`,
48	  // Globe hero, plus the same [gray][blue] tab strip as the "new" diagram.
49	  "open-homepage": `<svg viewBox="0 0 80 50" fill="none" xmlns="http://www.w3.org/2000/svg">
50	    <rect x="6" y="6" width="68" height="38" rx="6" stroke="currentColor" stroke-width="1.5"/>
51	    <path d="M6 17H74" stroke="currentColor" stroke-width="1.5"/>
