116	// Default background when the user hasn't chosen one — the bundled aurora photo.
117	export const DEFAULT_BACKGROUND = {
118	  type: "photo",
119	  value: "img/aurora.webp",
120	};
121	
122	// Photo-only appearance modifiers (transparency + blur + which color the photo
123	// fades toward). They apply to image backgrounds only, never colors/gradients.
124	const PHOTO_BLUR_MAX = 20;
125	export const DEFAULT_PHOTO_ADJUST = {
126	  transparency: 0, // % the photo fades toward the fade color (0 = full photo)
127	  blur: 0, // px of CSS blur() on the photo
128	  fade: "bw", // "bw" (light → #fff, dark → #000) | "accent" (sampled color)
129	};
130	
131	// Only image backgrounds carry the transparency/blur modifiers.
132	function isPhotoBackground(type) {
133	  return type === "photo" || type === "custom";
134	}
135	
136	function clampNumber(value, min, max, fallback) {
137	  const n = Number(value);
138	  if (!Number.isFinite(n)) return fallback;
139	  return Math.min(max, Math.max(min, n));
140	}
141	
142	// Translate the stored photo modifiers into the CSS custom properties the
143	// wallpaper pseudo-layers read (see meridian.css). For non-photo backgrounds
144	// the modifiers are neutralized so colors/gradients render untouched. This is
145	// pure interpolation against already-derived values (the live --accent var and
146	// the theme's black/white) — it never re-samples the photo's pixels, so it is
147	// cheap enough to call on every slider tick.
148	export function applyPhotoAdjustments(bg, adjust) {
149	  const root = document.documentElement;
150	  if (!bg || !isPhotoBackground(bg.type)) {
151	    root.style.setProperty("--photo-opacity", "1");
152	    root.style.setProperty("--photo-blur", "0px");
153	    root.style.setProperty("--photo-fade-color", "transparent");
154	    return;
155	  }
156	  const a = { ...DEFAULT_PHOTO_ADJUST, ...(adjust ?? {}) };
157	  const transparency = clampNumber(a.transparency, 0, 100, 0);
158	  const blur = clampNumber(a.blur, 0, PHOTO_BLUR_MAX, 0);
159	  root.style.setProperty("--photo-opacity", String(1 - transparency / 100));
160	  root.style.setProperty("--photo-blur", `${blur}px`);
161	  root.style.setProperty(
162	    "--photo-fade-color",
163	    a.fade === "bw" ? "var(--photo-fade-bw)" : "var(--accent)",
164	  );
165	}
166	
167	function generateSeeds(count = 12, exclude = new Set()) {
168	  const seeds = new Set();
169	  while (seeds.size < count) {
170	    const s = String(Math.floor(Math.random() * 9000) + 1000);
171	    if (!exclude.has(s)) seeds.add(s);
172	  }
173	  return [...seeds];
174	}
175	
176	export function createSettingsPanel(container) {
177	  let newTabBehavior = "meridian-view";
178	  let groupByDomain = false;
179	  let homepageUrl = "";
180	  let currentTheme = "system";
181	  let currentBg = DEFAULT_BACKGROUND;
182	  let customBgUrl = null;
183	  let photoSeeds = generateSeeds();
184	  let photoAdjust = { ...DEFAULT_PHOTO_ADJUST };
185	
186	  const panel = document.createElement("div");
187	
188	  // Settings are grouped into labeled sections; each control group is
189	  // appended to one of these rather than straight onto the panel.
190	  function makeSection(titleText) {
191	    const section = document.createElement("div");
192	    section.className = "settings-section";
193	    const heading = document.createElement("h3");
194	    heading.className = "settings-section-title";
195	    heading.textContent = titleText;
196	    section.appendChild(heading);
197	    return section;
198	  }
199	
200	  const appearanceSection = makeSection("Appearance");
201	  const searchSection = makeSection("Search");
202	  const tabsSection = makeSection("Tabs");
203	
204	  // --- Privacy & Data disclosure ---
205	  // Native details/summary keeps the disclosure keyboard-accessible while
206	  // allowing it to remain collapsed at the bottom of Settings by default.
207	  const privacySection = document.createElement("details");
208	  privacySection.className = "settings-section settings-privacy-section";
209	
210	  const privacySummary = document.createElement("summary");
211	  privacySummary.className = "settings-privacy-summary";
212	  privacySummary.textContent = "Privacy & Data";
213	  privacySection.appendChild(privacySummary);
214	
215	  const privacyGroup = document.createElement("div");
216	  privacyGroup.className = "settings-group settings-privacy-group";
217	
218	  const privacyIntro = document.createElement("p");
219	  privacyIntro.className = "settings-privacy-text";
220	  privacyIntro.textContent =
221	    "Meridian automatically captures a screenshot of your active tab to " +
222	    "show live thumbnails, and after an open tab finishes loading, reads " +
223	    "that page's meta description and heading (H1/H2) text to power local " +
224	    "open-tab search. Both happen automatically, without a separate " +
225	    "prompt, as part of the Tabs and Search features.";
226	
227	  const privacyStorage = document.createElement("p");
228	  privacyStorage.className = "settings-privacy-text";
229	  privacyStorage.textContent =
230	    "This data is stored locally in your Chrome profile. Meridian has no " +
231	    "server and never uploads it. Search options controls which " +
232	    "sources are searchable, and Thumbnails lets you " +
233	    "regenerate them on demand.";
234	
235	  const privacyOptional = document.createElement("p");
236	  privacyOptional.className = "settings-privacy-text";
237	  privacyOptional.textContent =
238	    "Bookmark and history access is never automatic — Meridian only asks " +
239	    "Chrome for that permission when you turn on Bookmarks or History " +
240	    "under Search options.";
241	
242	  const privacyLink = document.createElement("a");
243	  privacyLink.className = "settings-privacy-link";
244	  privacyLink.href = PRIVACY_POLICY_URL;
245	  privacyLink.target = "_blank";
246	  privacyLink.rel = "noopener noreferrer";
247	  privacyLink.textContent = "Read the full privacy policy";
248	
249	  privacyGroup.append(
250	    privacyIntro,
251	    privacyStorage,
252	    privacyOptional,
253	    privacyLink,
254	  );
255	  privacySection.appendChild(privacyGroup);
256	
257	  // --- New tab behavior ---
258	  const newTabGroup = document.createElement("div");
259	  newTabGroup.className = "settings-group";
260	
261	  const newTabLabel = document.createElement("span");
262	  newTabLabel.className = "settings-label";
263	  newTabLabel.textContent = "New Tab Behavior";
264	  newTabGroup.appendChild(newTabLabel);
265	
266	  // Card grid (radiogroup): each option shows a diagram of what happens,
267	  // replacing the native <select>. Full radio semantics + arrow-key nav.
268	  const newTabRow = document.createElement("div");
269	  newTabRow.className = "settings-behavior-grid";
270	  newTabRow.setAttribute("role", "radiogroup");
271	  newTabRow.setAttribute("aria-label", "New Tab Behavior");
272	  newTabGroup.appendChild(newTabRow);
273	
274	  function renderNewTabCards() {
275	    newTabRow.innerHTML = "";
276	    NEW_TAB_OPTIONS.forEach((o, i) => {
277	      const selected = o.id === newTabBehavior;
278	      const card = document.createElement("button");
279	      card.type = "button";
280	      card.className =
281	        "settings-behavior-card" + (selected ? " selected" : "");
282	      card.setAttribute("role", "radio");
283	      card.setAttribute("aria-checked", selected ? "true" : "false");
284	      card.tabIndex = selected ? 0 : -1;
285	
286	      const fig = document.createElement("span");
287	      fig.className = "settings-behavior-diagram";
288	      fig.setAttribute("aria-hidden", "true");
289	      fig.innerHTML = NEW_TAB_DIAGRAMS[o.id] ?? "";
290	      card.appendChild(fig);
291	
292	      const cap = document.createElement("span");
293	      cap.className = "settings-behavior-caption";
294	      cap.textContent = o.label;
295	      card.appendChild(cap);
296	
297	      card.addEventListener("click", () => selectNewTab(o.id));
298	      card.addEventListener("keydown", (e) => {
299	        let ni = -1;
300	        if (e.key === "ArrowRight" || e.key === "ArrowDown")
301	          ni = (i + 1) % NEW_TAB_OPTIONS.length;
302	        else if (e.key === "ArrowLeft" || e.key === "ArrowUp")
303	          ni = (i - 1 + NEW_TAB_OPTIONS.length) % NEW_TAB_OPTIONS.length;
304	        if (ni >= 0) {
305	          e.preventDefault();
306	          selectNewTab(NEW_TAB_OPTIONS[ni].id, true);
307	        }
308	      });
309	
310	      newTabRow.appendChild(card);
311	    });
312	  }
313	
314	  function selectNewTab(id, focus) {
315	    newTabBehavior = id;
316	    chrome.storage.sync.set({ newTabBehavior: id });
317	    syncNewTab();
318	    if (focus) {
319	      const el = newTabRow.querySelector(".settings-behavior-card.selected");
320	      if (el) el.focus();
321	    }
322	  }
323	
324	  // Only the "open a specific page" option needs a URL field; it appears
325	  // beneath the grid when that option is selected.
326	  const homepageField = document.createElement("div");
327	  homepageField.className = "settings-homepage-field";
328	
329	  const homepageInput = document.createElement("input");
330	  homepageInput.type = "url";
331	  homepageInput.className = "settings-homepage-input";
332	  homepageInput.placeholder = "https://example.com";
333	  homepageInput.setAttribute(
334	    "aria-describedby",
335	    "settings-homepage-feedback",
336	  );
337	
338	  const homepageFeedback = document.createElement("p");
339	  homepageFeedback.id = "settings-homepage-feedback";
340	  homepageFeedback.className = "settings-homepage-feedback";
341	  homepageFeedback.setAttribute("role", "alert");
342	
343	  function setHomepageError(message) {
344	    homepageInput.setCustomValidity(message);
345	    homepageInput.setAttribute("aria-invalid", String(!!message));
346	    homepageFeedback.textContent = message;
347	  }
348	
349	  homepageInput.addEventListener("change", () => {
350	    const normalized = normalizeHomepageUrl(homepageInput.value);
351	    if (normalized == null) {
352	      setHomepageError("Enter a complete http:// or https:// URL.");
353	      return;
354	    }
355	
356	    setHomepageError("");
357	    homepageUrl = normalized;
358	    homepageInput.value = normalized;
359	    chrome.storage.sync.set({ homepageUrl });
360	  });
361	  homepageInput.addEventListener("keydown", (e) => {
362	    if (e.key === "Enter") homepageInput.blur();
363	  });
364	  homepageField.append(homepageInput, homepageFeedback);
365	  newTabGroup.appendChild(homepageField);
366	
367	  function syncNewTab() {
368	    renderNewTabCards();
369	    homepageInput.value = homepageUrl;
370	    homepageField.classList.toggle(
371	      "hidden",
372	      newTabBehavior !== "open-homepage",
373	    );
374	  }
375	
376	  tabsSection.appendChild(newTabGroup);
377	
378	  // --- Group by domain ---
379	  const domainGroup = document.createElement("div");
380	  domainGroup.className = "settings-group";
381	
382	  const domainLabel = document.createElement("span");
383	  domainLabel.className = "settings-label";
384	  domainLabel.textContent = "Tab Organization";
385	  domainGroup.appendChild(domainLabel);
386	
387	  const toggleRow = document.createElement("label");
388	  toggleRow.className = "settings-toggle-row";
389	
390	  const toggleCheckbox = document.createElement("input");
391	  toggleCheckbox.type = "checkbox";
392	  toggleCheckbox.className = "settings-toggle";
393	  toggleCheckbox.setAttribute("aria-label", "Group unsorted tabs by domain");
394	
395	  const toggleLabel = document.createElement("span");
396	  toggleLabel.textContent = "Group unsorted tabs by domain";
397	
398	  toggleCheckbox.addEventListener("change", () => {
399	    groupByDomain = toggleCheckbox.checked;
400	    chrome.storage.sync.set({ groupByDomain });
401	    window.dispatchEvent(new CustomEvent("settings-changed"));
402	  });
403	
404	  toggleRow.appendChild(toggleCheckbox);
405	  toggleRow.appendChild(toggleLabel);
406	  domainGroup.appendChild(toggleRow);
407	  tabsSection.appendChild(domainGroup);
408	
409	  // --- Search options ---
410	  const localSearchGroup = document.createElement("div");
411	  localSearchGroup.className = "settings-group";
412	
413	  const localSearchLabel = document.createElement("span");
414	  localSearchLabel.className = "settings-label";
415	  localSearchLabel.textContent = "Search options";
416	  localSearchGroup.appendChild(localSearchLabel);
417	
418	  let localSearch = { ...DEFAULT_LOCAL_SEARCH };
419	
420	  const localSearchSources = [
421	    { key: "tabs", label: "Open Tabs" },
422	    { key: "bookmarks", label: "Bookmarks", optional: true },
423	    { key: "history", label: "History", optional: true },
424	  ];
425	
426	  const localSearchCheckboxes = {};
427	  const permissionStatus = document.createElement("p");
428	  permissionStatus.className = "settings-permission-status";
429	  permissionStatus.setAttribute("aria-live", "polite");
430	
431	  for (const source of localSearchSources) {
432	    const row = document.createElement("label");
433	    row.className = "settings-toggle-row";
434	
435	    const checkbox = document.createElement("input");
436	    checkbox.type = "checkbox";
437	    checkbox.className = "settings-toggle";
438	    checkbox.setAttribute("aria-label", source.label);
439	    checkbox.checked = localSearch[source.key];
440	
441	    const label = document.createElement("span");
442	    label.textContent = source.label;
443	
444	    checkbox.addEventListener("change", async () => {
445	      const requested = checkbox.checked;
446	      checkbox.disabled = true;
447	      try {
448	        const result = await setLocalSearchSourceEnabled(
449	          source.key,
450	          requested,
451	        );
452	        localSearch[source.key] = result.enabled;
453	        checkbox.checked = result.enabled;
454	        // Only the denial case needs explaining — a plain enable/disable is
455	        // already reflected by the checkbox itself.
456	        permissionStatus.textContent =
457	          source.optional && result.denied
458	            ? `${source.label} permission was not granted. This source remains off.`
459	            : "";
460	        window.dispatchEvent(new CustomEvent("settings-changed"));
461	      } catch {
462	        checkbox.checked = localSearch[source.key];
463	        permissionStatus.textContent =
464	          `Could not update ${source.label.toLowerCase()} access.`;
465	      } finally {
466	        checkbox.disabled = false;
467	      }
468	    });
469	
470	    row.appendChild(checkbox);
471	    row.appendChild(label);
472	    localSearchGroup.appendChild(row);
473	    localSearchCheckboxes[source.key] = checkbox;
474	  }
475	  localSearchGroup.appendChild(permissionStatus);
476	
477	  async function syncLocalSearchCheckboxes(savedSources) {
478	    const enabled = await getEnabledLocalSearchSources(savedSources);
479	    localSearch = { ...localSearch, ...enabled };
480	    for (const [key, checkbox] of Object.entries(localSearchCheckboxes)) {
481	      checkbox.checked = enabled[key];
482	    }
483	  }
484	
485	  chrome.storage.onChanged.addListener((changes, area) => {
486	    if (area !== "sync" || !changes.localSearch) return;
487	    syncLocalSearchCheckboxes(changes.localSearch.newValue);
488	  });
489	
490	  // (Appended below, after Search Engine, so the engine picker sits on top.)
491	
492	  // --- Search Engine ---
493	  let searchProvider = PROVIDERS[0].id;
494	
495	  const searchEngineGroup = document.createElement("div");
496	  searchEngineGroup.className = "settings-group";
497	
498	  const searchEngineLabel = document.createElement("span");
499	  searchEngineLabel.className = "settings-label";
500	  searchEngineLabel.textContent = "Search Engine";
501	  searchEngineGroup.appendChild(searchEngineLabel);
502	
503	  // Provider card grid (radiogroup): each card shows the provider's favicon +
504	  // name — the native <select> couldn't render provider marks.
505	  const searchEngineRow = document.createElement("div");
506	  searchEngineRow.className = "settings-provider-grid";
507	  searchEngineRow.setAttribute("role", "radiogroup");
508	  searchEngineRow.setAttribute("aria-label", "Search Engine");
509	  searchEngineGroup.appendChild(searchEngineRow);
510	
511	  function renderProviderCards() {
512	    searchEngineRow.innerHTML = "";
513	    PROVIDERS.forEach((p, i) => {
514	      const selected = p.id === searchProvider;
515	      const card = document.createElement("button");
516	      card.type = "button";
517	      card.className =
518	        "settings-provider-card" + (selected ? " selected" : "");
519	      card.setAttribute("role", "radio");
520	      card.setAttribute("aria-checked", selected ? "true" : "false");
521	      card.tabIndex = selected ? 0 : -1;
522	
523	      const icon = document.createElement("img");
524	      icon.className = "settings-provider-icon";
525	      icon.src = p.favicon;
526	      icon.alt = "";
527	      icon.setAttribute("aria-hidden", "true");
528	      icon.loading = "lazy";
529	      // If a favicon fails to load, hide the broken-image glyph gracefully.
530	      icon.addEventListener("error", () => {
531	        icon.classList.add("load-failed");
532	      });
533	      card.appendChild(icon);
534	
535	      const cap = document.createElement("span");
536	      cap.className = "settings-provider-name";
537	      cap.textContent = p.name;
538	      card.appendChild(cap);
