1045	// ── Auto accent: derive the accent hue from the active background ──
1046	// The accent tracks the background's dominant hue; the theme keeps saturation
1047	// and lightness (see meridian.css), and a contrast guard nudges lightness so
1048	// the accent can never collapse into a same-toned solid background.
1049	
1050	function hexToRgb(hex) {
1051	  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(hex).trim());
1052	  if (!m) return null;
1053	  let h = m[1];
1054	  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
1055	  const int = parseInt(h, 16);
1056	  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
1057	}
1058	
1059	function rgbToHsl(r, g, b) {
1060	  r /= 255;
1061	  g /= 255;
1062	  b /= 255;
1063	  const max = Math.max(r, g, b);
1064	  const min = Math.min(r, g, b);
1065	  const l = (max + min) / 2;
1066	  const d = max - min;
1067	  let h = 0;
1068	  let s = 0;
1069	  if (d !== 0) {
1070	    s = d / (1 - Math.abs(2 * l - 1));
1071	    if (max === r) h = ((g - b) / d) % 6;
1072	    else if (max === g) h = (b - r) / d + 2;
1073	    else h = (r - g) / d + 4;
1074	    h = Math.round(h * 60);
1075	    if (h < 0) h += 360;
1076	  }
1077	  return { h, s: Math.round(s * 100), l: Math.round(l * 100) };
1078	}
1079	
1080	// Pick the most saturated stop of a gradient/solid — the color that gives
1081	// the background its identity, not the muddy average of all stops.
1082	function dominantHex(str) {
1083	  const hexes = String(str).match(/#[0-9a-f]{6}|#[0-9a-f]{3}/gi);
1084	  if (!hexes || !hexes.length) return null;
1085	  let best = null;
1086	  for (const hx of hexes) {
1087	    const rgb = hexToRgb(hx);
1088	    if (!rgb) continue;
1089	    const hsl = rgbToHsl(...rgb);
1090	    if (!best || hsl.s > best.s) best = hsl;
1091	  }
1092	  return best;
1093	}
1094	
1095	// Find an image's dominant *vivid* hue via a saturation-weighted histogram.
1096	// A plain pixel average collapses to gray and throws the real color away.
1097	// Also returns the image's overall luminance (all opaque pixels) so callers
1098	// can decide whether content sitting on it needs light or dark text.
1099	function analyzeImage(url) {
1100	  return new Promise((resolve) => {
1101	    const img = new Image();
1102	    img.crossOrigin = "anonymous";
1103	    img.onload = () => {
1104	      try {
1105	        const size = 48;
1106	        const canvas = document.createElement("canvas");
1107	        canvas.width = size;
1108	        canvas.height = size;
1109	        const ctx = canvas.getContext("2d");
1110	        ctx.drawImage(img, 0, 0, size, size);
1111	        const { data } = ctx.getImageData(0, 0, size, size);
1112	        const BINS = 24;
1113	        const weight = new Array(BINS).fill(0);
1114	        const sSum = new Array(BINS).fill(0);
1115	        const lSum = new Array(BINS).fill(0);
1116	        const count = new Array(BINS).fill(0);
1117	        let lumSum = 0;
1118	        let lumN = 0;
1119	        for (let i = 0; i < data.length; i += 4) {
1120	          if (data[i + 3] < 125) continue;
1121	          lumSum += relLum(data[i], data[i + 1], data[i + 2]);
1122	          lumN += 1;
1123	          const hsl = rgbToHsl(data[i], data[i + 1], data[i + 2]);
1124	          // Skip grays and near black/white — they carry no hue identity.
1125	          if (hsl.s < 18 || hsl.l < 10 || hsl.l > 92) continue;
1126	          const bin = Math.floor((hsl.h / 360) * BINS) % BINS;
1127	          weight[bin] += hsl.s / 100; // vivid pixels weigh more
1128	          sSum[bin] += hsl.s;
1129	          lSum[bin] += hsl.l;
1130	          count[bin] += 1;
1131	        }
1132	        const lum = lumN ? lumSum / lumN : null;
1133	        let top = -1;
1134	        let topW = 0;
1135	        for (let b = 0; b < BINS; b += 1) {
1136	          if (weight[b] > topW) {
1137	            topW = weight[b];
1138	            top = b;
1139	          }
1140	        }
1141	        if (top < 0) return resolve({ dominant: null, lum }); // no vivid pixels
1142	        resolve({
1143	          dominant: {
1144	            h: Math.round(((top + 0.5) / BINS) * 360),
1145	            s: Math.round(sSum[top] / count[top]),
1146	            l: Math.round(lSum[top] / count[top]),
1147	          },
1148	          lum,
1149	        });
1150	      } catch {
1151	        resolve({ dominant: null, lum: null }); // cross-origin taint, etc.
1152	      }
1153	    };
1154	    img.onerror = () => resolve({ dominant: null, lum: null });
1155	    img.src = url;
1156	  });
1157	}
