1159	// Average relative luminance across every hex stop in a string.
1160	function averageLumOfHexes(str) {
1161	  const hexes = String(str).match(/#[0-9a-f]{6}|#[0-9a-f]{3}/gi);
1162	  if (!hexes || !hexes.length) return null;
1163	  let sum = 0;
1164	  let n = 0;
1165	  for (const hx of hexes) {
1166	    const rgb = hexToRgb(hx);
1167	    if (!rgb) continue;
1168	    sum += relLum(...rgb);
1169	    n += 1;
1170	  }
1171	  return n ? sum / n : null;
1172	}
1173	
1174	// Returns { dominant, lum } for the active background. `lum` is null for the
1175	// "none" background, which follows the theme's --bg (read live at apply time).
1176	async function analyzeBackground(bg, customDataUrl) {
1177	  if (!bg || bg.type === "none") return { dominant: null, lum: null };
1178	  if (bg.type === "solid") {
1179	    const rgb = hexToRgb(bg.value);
1180	    return {
1181	      dominant: rgb ? rgbToHsl(...rgb) : null,
1182	      lum: rgb ? relLum(...rgb) : null,
1183	    };
1184	  }
1185	  if (bg.type === "gradient") {
1186	    return { dominant: dominantHex(bg.value), lum: averageLumOfHexes(bg.value) };
1187	  }
1188	  if (bg.type === "photo") return analyzeImage(bg.value);
1189	  if (bg.type === "custom") {
1190	    return customDataUrl
1191	      ? analyzeImage(customDataUrl)
1192	      : { dominant: null, lum: null };
1193	  }
1194	  return { dominant: null, lum: null };
1195	}
1196	
1197	// ── Color math for the surface-contrast solver ──
1198	function hslToRgb(h, s, l) {
1199	  s /= 100;
1200	  l /= 100;
1201	  const c = (1 - Math.abs(2 * l - 1)) * s;
1202	  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
1203	  const m = l - c / 2;
1204	  let r = 0;
1205	  let g = 0;
1206	  let b = 0;
1207	  if (h < 60) [r, g, b] = [c, x, 0];
1208	  else if (h < 120) [r, g, b] = [x, c, 0];
1209	  else if (h < 180) [r, g, b] = [0, c, x];
1210	  else if (h < 240) [r, g, b] = [0, x, c];
1211	  else if (h < 300) [r, g, b] = [x, 0, c];
1212	  else [r, g, b] = [c, 0, x];
1213	  return [(r + m) * 255, (g + m) * 255, (b + m) * 255];
1214	}
1215	
1216	function relLum(r, g, b) {
1217	  const a = [r, g, b].map((v) => {
1218	    const n = v / 255;
1219	    return n <= 0.03928 ? n / 12.92 : ((n + 0.055) / 1.055) ** 2.4;
1220	  });
1221	  return 0.2126 * a[0] + 0.7152 * a[1] + 0.0722 * a[2];
1222	}
1223	
1224	function contrastRatio(l1, l2) {
1225	  const hi = Math.max(l1, l2);
1226	  const lo = Math.min(l1, l2);
1227	  return (hi + 0.05) / (lo + 0.05);
1228	}
1229	
1230	// Luminance of the actual --surface the accent renders on (cards, panels).
1231	function surfaceLum() {
1232	  const v = getComputedStyle(document.documentElement)
1233	    .getPropertyValue("--surface")
1234	    .trim();
1235	  const rgb = hexToRgb(v);
1236	  if (rgb) return relLum(...rgb);
1237	  return docIsDark() ? 0.035 : 1;
1238	}
1239	
1240	// Derived accents run a touch under full saturation — neon reads cheap.
1241	const ACCENT_SAT = 80;
1242	
1243	// Last resolved dominant + background luminance, cached so a theme switch can
1244	// re-run the solver and re-pick on-background text without re-sampling.
1245	let lastDominant = null;
1246	let lastBgLum = null;
1247	let accentGeneration = 0;
1248	
1249	function docIsDark() {
1250	  const t = document.documentElement.dataset.theme;
1251	  if (t === "dark") return true;
1252	  if (t === "light") return false;
1253	  return window.matchMedia("(prefers-color-scheme: dark)").matches;
1254	}
1255	
1256	function applyDerivedAccent(dominant) {
1257	  const root = document.documentElement;
1258	  // Grayscale / very desaturated → no meaningful hue; use the default.
1259	  if (!dominant || dominant.s < 12) {
1260	    root.style.removeProperty("--accent-hue");
1261	    root.style.removeProperty("--accent-sat");
1262	    root.style.removeProperty("--accent-light");
1263	    return;
1264	  }
1265	
1266	  // Solve for a lightness that clears a legible contrast against the SURFACE
1267	  // (where the accent actually lives), searching in the safe direction and
1268	  // staying inside a tasteful band so filled-accent glyphs stay readable too.
1269	  const hue = dominant.h;
1270	  const dark = docIsDark();
1271	  const surf = surfaceLum();
1272	  const target = 3.5;
1273	  const floor = dark ? 48 : 30;
1274	  const ceil = dark ? 70 : 50;
1275	  let l = dark ? 58 : 44;
1276	  const step = dark ? 2 : -2;
1277	  for (let i = 0; i < 40; i += 1) {
1278	    const [r, g, b] = hslToRgb(hue, ACCENT_SAT, l);
1279	    if (contrastRatio(relLum(r, g, b), surf) >= target) break;
1280	    l += step;
1281	    if (l <= floor) {
1282	      l = floor;
1283	      break;
1284	    }
1285	    if (l >= ceil) {
1286	      l = ceil;
1287	      break;
1288	    }
1289	  }
1290	
1291	  root.style.setProperty("--accent-hue", String(hue));
1292	  root.style.setProperty("--accent-sat", `${ACCENT_SAT}%`);
1293	  root.style.setProperty("--accent-light", `${l}%`);
1294	}
1295	
1296	// Content that sits directly on the background (lane headers) can't rely on the
1297	// theme's text color — the wallpaper may be light or dark regardless of theme.
1298	// Pick light or dark on-background text from the background's own luminance,
1299	// plus a contrasting text-shadow scrim so it survives busy photos.
1300	function applyOnBackground(lum) {
1301	  const root = document.documentElement;
1302	  let L = lum;
1303	  if (L == null) {
1304	    // "none" background follows the theme's --bg — read it live.
1305	    const v = getComputedStyle(root).getPropertyValue("--bg").trim();
1306	    const rgb = hexToRgb(v);
1307	    L = rgb ? relLum(...rgb) : docIsDark() ? 0.02 : 0.9;
1308	  }
1309	  if (L < 0.4) {
1310	    // Dark background → light text.
1311	    root.style.setProperty("--on-bg", "rgba(255, 255, 255, 0.95)");
1312	    root.style.setProperty("--on-bg-muted", "rgba(255, 255, 255, 0.72)");
1313	    root.style.setProperty("--on-bg-shadow", "0 1px 3px rgba(0, 0, 0, 0.55)");
1314	  } else {
1315	    // Light background → dark text.
1316	    root.style.setProperty("--on-bg", "rgba(0, 0, 0, 0.9)");
1317	    root.style.setProperty("--on-bg-muted", "rgba(0, 0, 0, 0.6)");
1318	    root.style.setProperty("--on-bg-shadow", "0 1px 2px rgba(255, 255, 255, 0.4)");
1319	  }
1320	}
1321	
1322	export async function applyAccentFromBackground(bg, customDataUrl = null) {
1323	  const generation = ++accentGeneration;
1324	  const resolvedCustomDataUrl = await customDataUrl;
1325	  if (generation !== accentGeneration) return;
1326	
1327	  const { dominant, lum } = await analyzeBackground(bg, resolvedCustomDataUrl);
1328	  if (generation !== accentGeneration) return;
1329	
1330	  lastDominant = dominant;
1331	  lastBgLum = lum;
1332	  applyDerivedAccent(dominant);
1333	  applyOnBackground(lum);
1334	}
1335	
1336	export function applyTheme(theme) {
1337	  const html = document.documentElement;
1338	  if (theme === "light") {
1339	    html.dataset.theme = "light";
1340	  } else if (theme === "dark") {
1341	    html.dataset.theme = "dark";
1342	  } else {
1343	    delete html.dataset.theme;
1344	  }
1345	  // Both the accent solver and the on-background text depend on the theme
1346	  // (surface + the "none" background follow it) — re-run them on switch.
1347	  applyDerivedAccent(lastDominant);
1348	  applyOnBackground(lastBgLum);
1349	}
1350	
1351	export function applyBackground(bg, customDataUrl = null) {
1352	  const root = document.documentElement;
1353	  root.style.removeProperty("--bg");
1354	  if (!bg || bg.type === "none") {
1355	    root.style.removeProperty("--bg-image");
1356	  } else if (bg.type === "solid") {
1357	    root.style.removeProperty("--bg-image");
1358	    root.style.setProperty("--bg", bg.value);
1359	  } else if (bg.type === "gradient") {
1360	    root.style.setProperty("--bg-image", bg.value);
1361	  } else if (bg.type === "photo") {
1362	    root.style.setProperty("--bg-image", `url("${bg.value}")`);
1363	  } else if (bg.type === "custom") {
1364	    if (customDataUrl) {
1365	      root.style.setProperty("--bg-image", `url("${customDataUrl}")`);
1366	    } else {
1367	      root.style.removeProperty("--bg-image");
1368	    }
1369	  }
1370	}
