}

/* ---- Settings privacy disclosure ---- */

.settings-privacy-summary {
  position: relative;
  margin: 0;
  padding: 0 26px 8px 0;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  font-size: 15px;
  font-weight: 600;
  list-style: none;
}

.settings-privacy-summary::-webkit-details-marker {
  display: none;
}

.settings-privacy-summary::after {
  position: absolute;
  top: 0;
  right: 4px;
  content: "›";
  color: var(--text-secondary);
  font-size: 20px;
  line-height: 1;
  transform: rotate(0deg);
  transition: transform 0.15s ease;
}

.settings-privacy-section[open] > .settings-privacy-summary::after {
  transform: rotate(90deg);
}

.settings-privacy-summary:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 2px;
}

.settings-privacy-group {
  margin: 14px 0 0;
}

.settings-privacy-text {
  margin: 0 0 10px;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}

.settings-privacy-text:last-of-type {
  margin-bottom: 12px;
}

.settings-privacy-link {
  display: inline-block;
  color: var(--accent);
  font-size: 13px;
  font-weight: 600;
  text-decoration: underline;
}

.settings-privacy-link:hover {
  text-decoration: none;
}

.settings-privacy-link:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ---- Settings action button ---- */

.settings-action-btn {
  width: 100%;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-primary);
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  transition:
    background var(--transition),
    color var(--transition);
}

.settings-action-btn:hover:not(:disabled) {
  background: var(--surface-hover);
}

.settings-action-btn:disabled {
  color: var(--text-secondary);
  cursor: default;
}

/* ---- Drag and drop ---- */

.tab-card.dragging {
  opacity: 0.5;
}

.drag-placeholder {
  min-height: 150px;

