// --- Emberstone Studio footer ---
// A deliberately minimal donationware credit: the studio brand mark, a short
// credit line, and two outbound links (studio site + Ko-fi). Static markup
// only — no chrome.* calls, no click tracking — so it never contacts the
// network until the user explicitly follows a link. Sits directly above the
// Privacy & Data disclosure at the very bottom of the panel.
const emberstoneFooter = document.createElement("div");
emberstoneFooter.className = "settings-section settings-emberstone";

const emberstoneLogo = document.createElement("img");
emberstoneLogo.className = "settings-emberstone-logo";
// Root-relative, matching how img/aurora.webp and the icon assets are
// referenced elsewhere. The SVG is a fixed multi-color mark (not theme
// adaptive), so one file serves both light and dark.
emberstoneLogo.src = "img/emberstone.svg";
// Decorative: the visible credit line beside it already names the studio, so
// an empty alt (matching the provider/theme icons) avoids a double read.
emberstoneLogo.alt = "";
emberstoneLogo.width = 40;
emberstoneLogo.height = 40;
emberstoneLogo.setAttribute("aria-hidden", "true");
emberstoneLogo.loading = "lazy";
// If the asset ever fails to load, hide the broken-image glyph gracefully.
emberstoneLogo.onerror = () => {
  emberstoneLogo.classList.add("load-failed");
};

const emberstoneCredit = document.createElement("p");
emberstoneCredit.className = "settings-emberstone-credit";
emberstoneCredit.textContent = "Developed by Emberstone Studio";

const emberstoneLinks = document.createElement("div");
emberstoneLinks.className = "settings-emberstone-links";

// Native <a href target="_blank" rel="noopener noreferrer"> links — the same
// safe outbound-link pattern as the privacy-policy link above. They open in a
// new tab, keeping the new-tab/settings context intact, and are keyboard
// focusable with a visible focus ring from .settings-action-btn.
const emberstoneSiteLink = document.createElement("a");
emberstoneSiteLink.className = "settings-action-btn settings-emberstone-link";
emberstoneSiteLink.href = "https://emberstone-studio.com";
emberstoneSiteLink.target = "_blank";
emberstoneSiteLink.rel = "noopener noreferrer";
emberstoneSiteLink.textContent = "See more from Emberstone Studio";

const emberstoneCoffeeLink = document.createElement("a");
emberstoneCoffeeLink.className =
  "settings-action-btn settings-emberstone-link";
emberstoneCoffeeLink.href = "https://ko-fi.com/emberstonestudio";
emberstoneCoffeeLink.target = "_blank";
emberstoneCoffeeLink.rel = "noopener noreferrer";
emberstoneCoffeeLink.textContent = "Buy us a coffee";

emberstoneLinks.append(emberstoneSiteLink, emberstoneCoffeeLink);
emberstoneFooter.append(emberstoneLogo, emberstoneCredit, emberstoneLinks);

// Keep the optional Privacy & Data disclosure last so primary settings
// remain immediately available; the Emberstone credit sits just above it.
panel.append(
  appearanceSection,
  searchSection,
  tabsSection,
  emberstoneFooter,
  privacySection,
);

