      homepageUrl = saved.homepageUrl ?? "";
      currentTheme = saved.theme ?? "system";
      currentBg = saved.background ?? DEFAULT_BACKGROUND;
      photoAdjust = { ...DEFAULT_PHOTO_ADJUST, ...(saved.photoAdjust ?? {}) };
